# NOTE: Arms A/B/C are the NATIVE radiance runtime — not vllm-expressible in this spec (RULE-6 GAP: recommend
# NOTE:   gen_campaign learn server: radiance | vllm engine kinds). Hand-added server blocks below the D block:
# NOTE:   A = Quark-MXFP4 .rad @ stilldeadcode/radiance:1.11.0 (baseline), B = same .rad @ 1.17.0,
# NOTE:   C = IQ4R-L-V4 .rad @ 1.17.0 — all 260000 ctx / 2 seqs / fp8 KV / --gpu-headroom-mib 596 /
# NOTE:   --num-speculative-tokens 7 (27b.conf), slugs a-*/b-*/c-* (same cells each).
# NOTE: Round 1 = 8 cells/arm: depths 10k/100k x tg 512/1024 x n 1/2, reps 1. Round 2 (--round 2, hand-added,
# NOTE:   ROUND-guarded) = 50k x tg{512,1024,4096} x n{1,2} + tg4096 x 10k/100k x n{1,2} (10 cells/arm).
# NOTE: KLD (WS3, bench/perf/kld_probe.py; method locked in research/ws3-kld-r2.md): paired greedy continuation
# NOTE:   (temp 0, logprobs 20, shared-prefix pairing, first-divergent position included; radiance never returns
# NOTE:   prompt logprobs so prompt-scoring cannot be the uniform mode — optional labeled bonus pass on sly pairs),
# NOTE:   KL(ref||arm) per sly kv4/kl_compare.py (floor for missing tokens => lower bound), cluster bootstrap
# NOTE:   CI (block = prompt) + pooled cross-check, 5-point live selftest per engine family (first radiance boot
# NOTE:   = arm A, first sly boot = arm D) that aborts the KLD pass only. Reference = Qwen__Qwen3.8-27B-FP8@
# NOTE:   017b9c7a on one dedicated boot (sly-radiance/qwen38-fp8, IMAGE pinned 1.11.0), its fetch cached in
# NOTE:   tmp/ (resumable). Calibration set: inputs/calibration-prompts.jsonl (file-head prompts, code-dominated
# NOTE:   mix from bench/workloads/corpus/, 128 prompts x ~200-2000-token heads, raw text no chat template),
# NOTE:   hash-pinned via inputs/calibration-manifest.jsonl + inputs/calibration.sha256. Noise floors: A-vs-B
# NOTE:   pair = engine-version floor; reference self-run = boot noise.
# NOTE: WS7 prologue (hand-added, before arm D): sly 1.11.0 first-boot phase breakdown (this boot = arm D's cold
# NOTE:   boot) -> stop -> warm reboot -> seconds; cache pre-check label from the session-1 CPU check.
set -uo pipefail
HERE="$(cd "$(dirname "$(readlink -f "${BASH_SOURCE[0]}")")" && pwd)"
ROOT="${ROOT:-$(git -C "$HERE" rev-parse --show-toplevel 2>/dev/null)}"
[ -n "$ROOT" ] || { echo "run.sh: cannot find the repo root (git toplevel of $HERE) -- set ROOT=" >&2; exit 1; }
CAMPAIGN_DIR="${CAMPAIGN_DIR:-$HERE}"
mkdir -p "$CAMPAIGN_DIR" && CAMPAIGN_DIR="$(cd "$CAMPAIGN_DIR" && pwd)"
# RUN_TAG (run-short.sh, or manually): isolates ALL outputs of this run in a unique dir under
# the gitignored tmp/ so repeated runs never overwrite each other (done markers included —
# a re-run with a new tag RE-DOES the cells, doubling the data; pin RUN_TAG to resume).
# Everything stays in project tmp/, never machine /tmp (repo rule — reboot wipes /tmp).
RUN_TAG="${RUN_TAG:-}"
if [ -n "$RUN_TAG" ]; then
  RUN_DIR="$CAMPAIGN_DIR/tmp/runs/$RUN_TAG"
  RAW="$RUN_DIR/tmp"; RES="$RUN_DIR/results"
  PROBE_CAMPAIGN="$RUN_DIR"          # engine-bench per-probe raw dirs follow the tag
else
  RUN_DIR=""; RAW="$CAMPAIGN_DIR/tmp"; RES="$CAMPAIGN_DIR/results"   # raw (ignored) / results (committed)
  PROBE_CAMPAIGN="$CAMPAIGN_DIR"
fi
mkdir -p "$RAW" "$RES"
EB="$ROOT/bench/perf/engine-bench"
GEN="$ROOT/bench/workloads/tmp"

# --- item 1: arg parsing -------------------------------------------------------
# WS_NO_MAIN=1 makes this file a sourceable library (used by run-arm.sh): arg parsing
# and the main flow are skipped; definitions, preflight and helpers still apply.
ROUND="${ROUND:-1}"; KLD_E="${KLD_E:-0}"
if [ -z "${WS_NO_MAIN:-}" ]; then
while [ $# -gt 0 ]; do
  case "$1" in
    --round) [ $# -ge 2 ] || { echo "--round needs a value (2)" >&2; exit 1; }; ROUND=$2; shift ;;
    --kld)   [ $# -ge 2 ] || { echo "--kld needs a target (heretic)" >&2; exit 1; }
             case "$2" in heretic) KLD_E=1 ;; *) echo "unknown --kld target '$2' (only: heretic)" >&2; exit 1 ;; esac
             shift ;;
    *) echo "unknown arg: $1 (usage: run.sh [--round 2] [--kld heretic])" >&2; exit 1 ;;
  esac
  shift
done
fi
{ [ "$ROUND" -ge 1 ] && [ "$ROUND" -le 2 ]; } || { echo "ROUND must be 1 or 2" >&2; exit 1; }

# --- item 2: pins (D6 re-check, 2026-11-09 — MEASURED; 2026-11-10: sly target
